// Auto-generated from index.html
export const jsContent = "\n    (function(){\n      var current = 0;\n      var slides = [\n        { label:'Efekty pierwszej edycji', title:'W rok — 7 parafii, ponad 300 osób' },\n        { label:'Druga edycja', title:'13 nowych parafii — start od września 2026' }\n      ];\n      window.editionSlide = function(dir) {\n        document.getElementById('edition-slide-' + current).style.display = 'none';\n        current = Math.max(0, Math.min(slides.length - 1, current + dir));\n        document.getElementById('edition-slide-' + current).style.display = '';\n        document.getElementById('edition-label').textContent = slides[current].label;\n        document.getElementById('edition-title').textContent = slides[current].title;\n        document.getElementById('edition-counter').textContent = (current+1) + ' / ' + slides.length;\n        document.getElementById('btn-prev').disabled = current === 0;\n        document.getElementById('btn-prev').style.opacity = current === 0 ? '.35' : '1';\n        document.getElementById('btn-next').disabled = current === slides.length - 1;\n        document.getElementById('btn-next').style.opacity = current === slides.length - 1 ? '.35' : '1';\n      };\n    })();\n    \n\n  const pages = ['home','oferta','grafik','cennik','onas','kontakt','faq','parafia','sklep','instruktor','imprezy','warsztaty','sylwester','regulamin','regulamin-imprez'];\n\n  function toggleReg(el) {\n    el.classList.toggle('open');\n    el.nextElementSibling.classList.toggle('open');\n  }\n\n  function showPage(id) {\n    pages.forEach(p => {\n      const el = document.getElementById('page-' + p);\n      if (el) el.classList.remove('active');\n    });\n    const target = document.getElementById('page-' + id);\n    if (target) {\n      target.classList.add('active');\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    }\n    // update active nav\n    document.querySelectorAll('.nav__links a').forEach(a => a.classList.remove('active'));\n    const navEl = document.getElementById('nav-' + id);\n    if (navEl) navEl.classList.add('active');\n    return false;\n  }\n\n  function toggleMobile() {\n    document.getElementById('mobileMenu').classList.toggle('open');\n  }\n  function closeMobile() {\n    document.getElementById('mobileMenu').classList.remove('open');\n  }\n\n  function toggleFaq(el) {\n    const isOpen = el.classList.contains('open');\n    document.querySelectorAll('.faq-q').forEach(q => {\n      q.classList.remove('open');\n      q.nextElementSibling.classList.remove('open');\n    });\n    if (!isOpen) {\n      el.classList.add('open');\n      el.nextElementSibling.classList.add('open');\n    }\n  }\n\n  // set home as active on load\n  document.getElementById('nav-home').classList.add('active');\n";
